"""Wrapper around yt_dlp for metadata extraction and track downloading."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable, Literal

import yt_dlp

from yt_sync_core.exceptions import ExtractionError
from yt_sync_core.models import SyncConfig

# yt-dlp statuses indicating that a video is no longer accessible
_UNAVAILABLE_STATUSES: frozenset[str] = frozenset(
    {"private", "unavailable", "needs_auth", "subscriber_only"}
)

# Title markers generated by yt-dlp for inaccessible videos
_UNAVAILABLE_TITLE_MARKERS: tuple[str, ...] = (
    "[private video]",
    "[deleted video]",
    "[removed]",
)


@dataclass(frozen=True)
class RemoteTrack:
    """Track representation as observed on YouTube (remote).

    Attributes:
        video_id: YouTube video identifier (e.g. ``dQw4w9WgXcQ``).
        title: Video title on YouTube.
        is_available: ``False`` if the video is private, deleted, or unavailable.
    """

    video_id: str
    title: str
    is_available: bool = True


def _is_entry_unavailable(entry: dict[str, Any]) -> bool:
    """Determine whether a playlist entry is unavailable."""
    availability: str = entry.get("availability") or ""
    if availability in _UNAVAILABLE_STATUSES:
        return True
    title: str = (entry.get("title") or "").lower()
    return any(marker in title for marker in _UNAVAILABLE_TITLE_MARKERS)


def _build_remote_track(entry: dict[str, Any]) -> RemoteTrack:
    """Build a :class:`RemoteTrack` from a yt-dlp entry dictionary."""
    video_id: str = entry["id"]
    title: str = entry.get("title") or video_id
    unavailable = _is_entry_unavailable(entry)
    return RemoteTrack(video_id=video_id, title=title, is_available=not unavailable)


class PlaylistExtractor:
    """High-level interface to yt-dlp.

    All methods use ``yt_dlp.YoutubeDL`` as a context manager; no network
    requests are performed outside ``fetch_playlist`` and ``download_tracks``.
    """

    def __init__(
        self,
        *,
        config: SyncConfig | None = None,
        normalize_audio: bool = True,
        target_lufs: float = -14.0,
        true_peak: float = -1.5,
        audio_format: Literal["m4a", "mp3"] = "m4a",
        audio_quality: str = "192",
    ) -> None:
        if config is not None:
            self._config = config
        else:
            self._config = SyncConfig(
                normalize_audio=normalize_audio,
                target_lufs=target_lufs,
                true_peak=true_peak,
                audio_format=audio_format,
                audio_quality=audio_quality,
            )

    @property
    def config(self) -> SyncConfig:
        """Active synchronization and audio normalization configuration."""
        return self._config

    # ------------------------------------------------------------------
    # Metadata extraction
    # ------------------------------------------------------------------

    def fetch_playlist_details(self, url: str) -> tuple[str, list[RemoteTrack]]:
        """Fetch playlist title and tracks without downloading.

        Args:
            url: Complete URL of the YouTube playlist.

        Returns:
            Tuple of (playlist_title, list_of_remote_tracks).

        Raises:
            ExtractionError: If yt-dlp fails to extract playlist info.
        """
        opts: dict[str, Any] = {
            "quiet": True,
            "no_warnings": True,
            "ignoreerrors": True,
            "extract_flat": True,
        }

        with yt_dlp.YoutubeDL(opts) as ydl:
            info: dict[str, Any] | None = ydl.extract_info(url, download=False)

        if info is None:
            raise ExtractionError(
                f"yt-dlp could not extract information for URL: {url}"
            )

        title: str = info.get("title") or "YouTube Playlist"
        entries: list[dict[str, Any]] = info.get("entries") or []
        return title, [_build_remote_track(e) for e in entries]

    def fetch_playlist(self, url: str) -> list[RemoteTrack]:
        """Fetch the list of tracks from a YouTube playlist without downloading.

        Args:
            url: Complete URL of the YouTube playlist.

        Returns:
            List of :class:`RemoteTrack` instances.

        Raises:
            ExtractionError: If yt-dlp fails to extract playlist info.
        """
        _, tracks = self.fetch_playlist_details(url)
        return tracks

    # ------------------------------------------------------------------
    # Targeted downloads
    # ------------------------------------------------------------------

    def download_tracks(
        self,
        video_ids: list[str],
        *,
        output_dir: str,
        progress_callback: Callable[[dict[str, Any]], None] | None = None,
        normalize_audio: bool | None = None,
        target_lufs: float | None = None,
        true_peak: float | None = None,
        audio_format: Literal["m4a", "mp3"] | str | None = None,
        audio_quality: str | None = None,
        config: SyncConfig | None = None,
    ) -> None:
        """Download specified videos by their IDs.

        Args:
            video_ids: List of YouTube video IDs to download.
            output_dir: Destination directory for audio files.
            progress_callback: Optional progress hook callback invoked by yt-dlp.
            normalize_audio: Optional override for audio loudness normalization.
            target_lufs: Optional override for target LUFS.
            true_peak: Optional override for true peak level in dBTP.
            audio_format: Optional override for target audio format ("m4a" or "mp3").
            audio_quality: Optional override for audio quality (e.g. "192").
            config: Optional SyncConfig instance overriding default settings.
        """
        if not video_ids:
            return

        effective_cfg = config or self._config
        eff_normalize = (
            normalize_audio
            if normalize_audio is not None
            else effective_cfg.normalize_audio
        )
        eff_target_lufs = (
            target_lufs if target_lufs is not None else effective_cfg.target_lufs
        )
        eff_true_peak = (
            true_peak if true_peak is not None else effective_cfg.true_peak
        )
        eff_audio_format = (
            audio_format if audio_format is not None else effective_cfg.audio_format
        )
        eff_audio_quality = (
            audio_quality if audio_quality is not None else effective_cfg.audio_quality
        )

        hooks: list[Callable[[dict[str, Any]], None]] = []
        if progress_callback is not None:
            hooks.append(progress_callback)

        opts: dict[str, Any] = {
            "quiet": True,
            "no_warnings": True,
            "ignoreerrors": True,
            "outtmpl": f"{output_dir}/%(title)s.%(ext)s",
            "format": "bestaudio/best",
            "progress_hooks": hooks,
            "postprocessors": [
                {
                    "key": "FFmpegExtractAudio",
                    "preferredcodec": eff_audio_format,
                    "preferredquality": eff_audio_quality,
                }
            ],
        }

        if eff_normalize:
            opts["postprocessor_args"] = {
                "ExtractAudio": [
                    "-af",
                    f"loudnorm=I={eff_target_lufs}:TP={eff_true_peak}:LRA=11",
                ]
            }

        urls = [f"https://www.youtube.com/watch?v={vid}" for vid in video_ids]

        with yt_dlp.YoutubeDL(opts) as ydl:
            ydl.download(urls)
